@@ -40,3 +40,17 @@ export function extractStopReason(chunk: MessageChunk): string | null {
 export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
   return chunk.type === 'stop' ? chunk.usage : undefined;
 }
+
+// A round that reported nothing cannot turn a reported total undefined or NaN; only reported fields add.
+export function addUsage(
+  total: UsageMetadata | undefined,
+  usage: UsageMetadata | undefined
+): UsageMetadata | undefined {
+  if (total === undefined) return usage;
+  if (usage === undefined) return total;
+  return {
+    inputTokens: total.inputTokens + usage.inputTokens,
+    outputTokens: total.outputTokens + usage.outputTokens,
+    totalTokens: total.totalTokens + usage.totalTokens,
+  };
+}
